"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import { AdminQuestionEditor, adminQuestionFormFrom, blankAdminQuestionForm, type AdminQuestionForm, type AdminQuestionStructureNode } from "@/components/admin/admin-question-editor";
import { AdminQuestionConference } from "@/components/admin/admin-question-conference";
import { AdminQuestionConferenceLists } from "@/components/admin/admin-question-conference-lists";
import { QuestionRichEditor } from "@/components/admin/question-rich-editor";
import { compareQuestionStructureNames } from "@/lib/questoes-structure";
import { LawStructureAdmin } from "@/components/admin/law-structure-admin";
import { LawQuestionShadows } from "@/components/admin/law-question-shadows";
