type Law = { id: number; slug: string; titulo: string };
type SearchResult = { id: string; structure_id: number | null; pergunta_trecho: string; resposta: "Certo" | "Errado"; artigo: string | null; assunto: string | null; ordem: string; ativo: boolean; updated_at: string };
type SearchResponse = { results: SearchResult[]; total: number; range: { first_order: string | null; last_order: string | null }; page: number; limit: number; pages: number };
type FullQuestion = AdminQuestionForm & { id: string; ativo: boolean };
type DeletionCampaign = { id: string; aluno_id: string; nome: string | null; email: string | null; concluida: boolean; abandonada: boolean; is_requesting_admin: boolean };
type DeletionSummary = { questions_count: number; structures_count: number; substructures_count: number; campaigns: DeletionCampaign[]; campaigns_count: number; answers_count: number; progresses_count: number; requires_confirmation: boolean; dependencies_count: number };
type BulkScope = "structure" | "results" | "all";
type BulkEditPreview = { field: QuestionEditableField; value: unknown; selection_count: number; changed_count: number; unchanged_count: number; sample: Array<{ id: string; before: unknown; after: unknown }>; expected: Array<{ id: string; before: unknown }> };
type BulkTextReplacementPreview = { field: QuestionTextReplaceField; find: string; replace: string; selection_count: number; changed_count: number; unchanged_count: number; sample: Array<{ id: string; before: unknown; after: unknown }>; expected: Array<{ id: string; before: unknown }> };

const answers: Array<{ value: AdminQuestionSearchFilter; label: string }> = [{ value: "all", label: "Todos os gabaritos" }, { value: "certo", label: "Certo" }, { value: "errado", label: "Errado" }, { value: "unstructured", label: "Sem estrutura" }];
const sortOptions: Array<{ value: AdminQuestionSearchSort; label: string }> = [{ value: "recent", label: "Mais recentes" }, { value: "ordem_asc", label: "Ordem crescente" }, { value: "ordem_desc", label: "Ordem decrescente" }];
async function readJson(response: Response) { const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(typeof body.error === "string" ? body.error : "Não foi possível concluir a operação."); return body; }
async function post(body: Record<string, unknown>) { return fetch("/api/admin/questoes", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }).then(readJson); }
function HighlightedText({ text, query }: { text: string; query: string }) { const terms = adminQuestionSearchTerms(query).map((term) => term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")); if (!terms.length) return <>{text}</>; const expression = new RegExp(`(${terms.join("|")})`, "gi"); return <>{text.split(expression).map((part, index) => terms.some((term) => new RegExp(`^${term}$`, "i").test(part)) ? <mark className="rounded bg-amber-100 px-0.5" key={`${part}-${index}`}>{part}</mark> : part)}</>; }

export function AdminLawQuestions({ law, initialStructure, initialStructureCounts, initialQuestion = null, initialDraft = null, sourceLegisBotId = null, returnHref = "", initialView = "ativas", conflicts = null, conflictFilters = { law: law.slug } }: { law: Law; initialStructure: AdminQuestionStructureNode[]; initialStructureCounts: Record<number, number>; initialQuestion?: FullQuestion | null; initialDraft?: AdminQuestionForm | null; sourceLegisBotId?: number | null; returnHref?: string; initialView?: "ativas" | "conflitos" | "sombra"; conflicts?: Awaited<ReturnType<typeof import("@/lib/admin-article-conflicts-server").listArticleSourceConflicts>> | null; conflictFilters?: { law?: string; type?: string; typeMode?: "any" | "all"; ordem_sort?: string } }) {
  const [nodes, setNodes] = useState(initialStructure);
  const [structureCounts, setStructureCounts] = useState(initialStructureCounts);
  const [reviewedStructures, setReviewedStructures] = useState<Set<number>>(new Set()); const [lawReviewed, setLawReviewed] = useState(false); const [reviewSaving, setReviewSaving] = useState<number | "law" | null>(null);
  const [query, setQuery] = useState(""); const [debouncedQuery, setDebouncedQuery] = useState(""); const [filter, setFilter] = useState<AdminQuestionSearchFilter>("all"); const [sort, setSort] = useState<AdminQuestionSearchSort>("recent"); const [article, setArticle] = useState(""); const [structureId, setStructureId] = useState<number | null>(null);
  const [page, setPage] = useState(1); const [results, setResults] = useState<SearchResult[]>([]); const [total, setTotal] = useState(0); const [resultRange, setResultRange] = useState<{ first_order: string | null; last_order: string | null }>({ first_order: null, last_order: null }); const [pages, setPages] = useState(1); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [message, setMessage] = useState(""); const [refresh, setRefresh] = useState(0); const [shadowVersion, setShadowVersion] = useState(0);
  const initialForm = initialQuestion ? adminQuestionFormFrom(initialQuestion) : initialDraft;
  const [editorOpen, setEditorOpen] = useState(Boolean(initialQuestion || initialDraft)); const [editingId, setEditingId] = useState<string | null>(initialQuestion?.id ?? null); const [form, setForm] = useState<AdminQuestionForm>(initialForm ?? blankAdminQuestionForm()); const [original, setOriginal] = useState<AdminQuestionForm | null>(initialForm); const [saving, setSaving] = useState(false); const [editorError, setEditorError] = useState("");
  const [deletionSummary, setDeletionSummary] = useState<DeletionSummary | null>(null); const [deleteConfirmation, setDeleteConfirmation] = useState(""); const [moveOpen, setMoveOpen] = useState(false); const [moveDestination, setMoveDestination] = useState<number | null>(null);
  const [bulkOpen, setBulkOpen] = useState(false); const [bulkScope, setBulkScope] = useState<BulkScope>("results"); const [bulkSummary, setBulkSummary] = useState<DeletionSummary | null>(null); const [bulkConfirmation, setBulkConfirmation] = useState("");
  const [conferenceOpen, setConferenceOpen] = useState(false); const [conferenceListsOpen, setConferenceListsOpen] = useState(false); const [conferenceList, setConferenceList] = useState<{ id: string; nome: string } | null>(null);
  const [questionView, setQuestionView] = useState<"ativas" | "conflitos" | "sombra">(initialView);
  const [selectedQuestionIds, setSelectedQuestionIds] = useState<string[]>([]); const [bulkEditOpen, setBulkEditOpen] = useState(false); const [bulkEditMode, setBulkEditMode] = useState<"edit" | "move" | "replace">("edit"); const [bulkEditScope, setBulkEditScope] = useState<BulkQuestionEditScope>("selected"); const [bulkEditField, setBulkEditField] = useState<QuestionEditableField>("total_artigos"); const [bulkEditValue, setBulkEditValue] = useState<unknown>(null); const [bulkEditPreview, setBulkEditPreview] = useState<BulkEditPreview | null>(null); const [bulkReplaceFind, setBulkReplaceFind] = useState(""); const [bulkReplaceValue, setBulkReplaceValue] = useState(""); const [bulkReplacePreview, setBulkReplacePreview] = useState<BulkTextReplacementPreview | null>(null); const [bulkEditCompletion, setBulkEditCompletion] = useState<string | null>(null);
  const titleRef = useRef<HTMLDivElement>(null); const savingRef = useRef(false);
  const structureMap = useMemo(() => new Map(nodes.map((node) => [node.id, node])), [nodes]);
  const structurePath = (target: number | null) => { const names: string[] = []; for (let node = target ? structureMap.get(target) : undefined; node; node = node.parent_id ? structureMap.get(node.parent_id) : undefined) names.unshift(node.nome); return names.join(" › "); };
  const selectedStructurePath = structureId ? structurePath(structureId).split(" › ").filter(Boolean) : [];
  const resultIds = results.map((item) => item.id); const previousId = editingId ? questionResultNeighbor(resultIds, editingId, -1) : null; const nextId = editingId ? questionResultNeighbor(resultIds, editingId, 1) : null;

  useEffect(() => { const timeout = window.setTimeout(() => { setDebouncedQuery(query.trim()); setPage(1); }, 350); return () => window.clearTimeout(timeout); }, [query]);
  useEffect(() => { const controller = new AbortController(); setLoading(true); setError(""); const params = new URLSearchParams({ law_slug: law.slug, mode: "search", q: debouncedQuery, filter, sort, article, page: String(page), limit: "30" }); if (structureId) params.set("structure_id", String(structureId)); void fetch(`/api/admin/questoes?${params}`, { cache: "no-store", signal: controller.signal }).then(readJson).then((body: SearchResponse) => { setResults(body.results); setTotal(body.total); setResultRange(body.range); setPages(body.pages); }).catch((caught) => { if (!(caught instanceof DOMException && caught.name === "AbortError")) setError(caught instanceof Error ? caught.message : "Não foi possível pesquisar as questões."); }).finally(() => { if (!controller.signal.aborted) setLoading(false); }); return () => controller.abort(); }, [law.slug, debouncedQuery, filter, sort, article, structureId, page, refresh]);
  useEffect(() => { const controller = new AbortController(); void fetch(`/api/admin/questoes?law_slug=${encodeURIComponent(law.slug)}&mode=structure-reviews`, { cache: "no-store", signal: controller.signal }).then(readJson).then((body: { reviewed: number[]; law_reviewed: boolean }) => { setReviewedStructures(new Set(body.reviewed)); setLawReviewed(body.law_reviewed); }).catch((caught) => { if (!(caught instanceof DOMException && caught.name === "AbortError")) setError(caught instanceof Error ? caught.message : "Não foi possível carregar as marcações de conferência."); }); return () => controller.abort(); }, [law.slug]);
  useEffect(() => { const controller = new AbortController(); void fetch(`/api/admin/questoes?law_slug=${encodeURIComponent(law.slug)}&mode=structure-counts`, { cache: "no-store", signal: controller.signal }).then(readJson).then((body: { counts: Record<number, number> }) => setStructureCounts(body.counts)).catch((caught) => { if (!(caught instanceof DOMException && caught.name === "AbortError")) setError(caught instanceof Error ? caught.message : "Não foi possível carregar as quantidades da estrutura."); }); return () => controller.abort(); }, [law.slug, refresh]);
  useEffect(() => { if (!editorOpen) return; const overflow = document.body.style.overflow; const focus = document.activeElement instanceof HTMLElement ? document.activeElement : null; const escape = (event: KeyboardEvent) => { if (event.key === "Escape" && !savingRef.current) setEditorOpen(false); }; document.body.style.overflow = "hidden"; document.addEventListener("keydown", escape); titleRef.current?.focus(); return () => { document.body.style.overflow = overflow; document.removeEventListener("keydown", escape); focus?.focus(); }; }, [editorOpen]);

  async function reloadStructure() { const body = await fetch(`/api/admin/questoes?law_slug=${encodeURIComponent(law.slug)}`, { cache: "no-store" }).then(readJson) as { structure: AdminQuestionStructureNode[] }; setNodes(body.structure); setRefresh((value) => value + 1); }
  function newQuestion(target = structureId) { setEditingId(null); setForm({ ...blankAdminQuestionForm(), structure_id: target }); setOriginal(null); setEditorError(""); setEditorOpen(true); }
  function newShadowQuestion(data: AdminQuestionForm, notice: string) { setQuestionView("ativas"); setEditingId(null); setForm(data); setOriginal(null); setEditorError(""); setMessage(notice); setEditorOpen(true); }
  async function editQuestion(id: string) { setEditorError(""); setError(""); try { const params = new URLSearchParams({ law_slug: law.slug, question_id: id }); const body = await fetch(`/api/admin/questoes?${params}`, { cache: "no-store" }).then(readJson) as { question: FullQuestion }; const next = adminQuestionFormFrom(body.question); setEditingId(body.question.id); setForm(next); setOriginal(next); setEditorOpen(true); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível abrir a questão."); } }
  function navigateToQuestion(id: string) { if (original && JSON.stringify(form) !== JSON.stringify(original) && !window.confirm("Há alterações não salvas. Deseja descartá-las e abrir outra questão?")) return; void editQuestion(id); }
  async function save(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const intent = ((event.nativeEvent as SubmitEvent).submitter as HTMLButtonElement | null)?.value; const savedId = editingId; const goNext = intent === "next" ? nextId : null; savingRef.current = true; setSaving(true); setEditorError(""); setMessage(""); try { const saved = await post({ action: savedId ? "atualizar" : "criar", law_slug: law.slug, id: savedId, data: form, legisbot_id: !savedId ? sourceLegisBotId : null }) as FullQuestion; setMessage(savedId ? "Questão atualizada sem alterar o UUID." : "Questão cadastrada com novo UUID."); setRefresh((value) => value + 1); setShadowVersion((value) => value + 1); if (returnHref && savedId === initialQuestion?.id) { window.location.assign(returnHref); return; } if (goNext) await editQuestion(goNext); else { setEditingId(saved.id); const next = adminQuestionFormFrom(saved); setForm(next); setOriginal(next); } } catch (caught) { setEditorError(caught instanceof Error ? caught.message : "Não foi possível salvar a questão."); } finally { savingRef.current = false; setSaving(false); } }
  function duplicateQuestion() { setEditingId(null); setOriginal(null); setEditorError("Altere a ordem ou o enunciado antes de salvar; a unicidade da importação será validada."); setMessage("Cópia preparada. O novo registro receberá outro UUID ao salvar."); }
  async function askDeleteQuestion() { if (!editingId) return; setSaving(true); setEditorError(""); try { setDeletionSummary(await post({ action: "resumo_exclusao_questao", law_slug: law.slug, id: editingId }) as DeletionSummary); setDeleteConfirmation("EXCLUIR"); } catch (caught) { setEditorError(caught instanceof Error ? caught.message : "Não foi possível analisar a exclusão."); } finally { setSaving(false); } }
  async function deleteQuestion() { if (!editingId) return; setSaving(true); try { await post({ action: "excluir_questao", law_slug: law.slug, id: editingId, confirmation: deleteConfirmation }); setDeletionSummary(null); setEditorOpen(false); setEditingId(null); setMessage("Questão e campanhas afetadas excluídas definitivamente."); setRefresh((value) => value + 1); } catch (caught) { setEditorError(caught instanceof Error ? caught.message : "Não foi possível excluir a questão."); } finally { setSaving(false); } }
  function bulkPayload() { return { law_slug: law.slug, scope: bulkScope, structure_id: bulkScope === "structure" ? structureId : null, query: debouncedQuery, filter, article }; }
  async function askBulkDelete() { if (bulkScope === "structure" && !structureId) { setError("Selecione uma estrutura antes de excluir suas questões e descendentes."); return; } setSaving(true); setError(""); try { setBulkSummary(await post({ action: "resumo_exclusao_questoes", ...bulkPayload() }) as DeletionSummary); setBulkConfirmation("EXCLUIR"); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível analisar a exclusão em massa."); } finally { setSaving(false); } }
  async function deleteBulkQuestions() { setSaving(true); try { await post({ action: "excluir_questoes", ...bulkPayload(), confirmation: bulkConfirmation }); setBulkSummary(null); setBulkOpen(false); setMessage("Questões e campanhas afetadas excluídas definitivamente; a estrutura foi preservada."); setRefresh((value) => value + 1); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível excluir as questões."); } finally { setSaving(false); } }
  function bulkEditPayload() { return { law_slug: law.slug, scope: bulkEditScope, field: bulkEditField, value: bulkEditValue, question_ids: bulkEditScope === "selected" ? selectedQuestionIds : undefined, query: debouncedQuery, filter, article, structure_id: structureId }; }
  async function previewBulkEdit() { if (bulkEditScope === "selected" && !selectedQuestionIds.length) { setError("Selecione ao menos uma questão para esta abrangência."); return; } setSaving(true); setError(""); try { setBulkEditPreview(await post({ action: "previsualizar_edicao_lote", ...bulkEditPayload() }) as BulkEditPreview); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível gerar a prévia da edição em lote."); } finally { setSaving(false); } }
  async function applyBulkEdit() { if (!bulkEditPreview) return; setSaving(true); setError(""); try { const result = await post({ action: "aplicar_edicao_lote", ...bulkEditPayload(), expected: bulkEditPreview.expected }) as { changed_count: number }; const completion = `${result.changed_count} questão(ões) atualizada(s), sem alterar UUIDs, campanhas ou progresso.`; setBulkEditCompletion(completion); setMessage(completion); setRefresh((value) => value + 1); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível aplicar a edição em lote."); } finally { setSaving(false); } }
  function bulkTextReplacementPayload() { return { law_slug: law.slug, scope: bulkEditScope, field: bulkEditField, find: bulkReplaceFind, replace: bulkReplaceValue, question_ids: bulkEditScope === "selected" ? selectedQuestionIds : undefined, query: debouncedQuery, filter, article, structure_id: structureId }; }
  async function previewBulkTextReplacement() { if (bulkEditScope === "selected" && !selectedQuestionIds.length) { setError("Selecione ao menos uma questão para esta abrangência."); return; } setSaving(true); setError(""); try { setBulkReplacePreview(await post({ action: "previsualizar_substituicao_lote", ...bulkTextReplacementPayload() }) as BulkTextReplacementPreview); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível gerar a prévia da substituição."); } finally { setSaving(false); } }
  async function applyBulkTextReplacement() { if (!bulkReplacePreview) return; setSaving(true); setError(""); try { const result = await post({ action: "aplicar_substituicao_lote", ...bulkTextReplacementPayload(), expected: bulkReplacePreview.expected }) as { changed_count: number }; const completion = `${result.changed_count} questão(ões) atualizada(s) por substituição de texto, sem alterar UUIDs, campanhas ou progresso.`; setBulkEditCompletion(completion); setMessage(completion); setRefresh((value) => value + 1); } catch (caught) { setError(caught instanceof Error ? caught.message : "Não foi possível aplicar a substituição em lote."); } finally { setSaving(false); } }
  function toggleQuestion(id: string) { setSelectedQuestionIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); }
  function toggleAllVisibleQuestions() { setSelectedQuestionIds((current) => { const visible = results.map((question) => question.id); const visibleSet = new Set(visible); const allVisibleSelected = visible.length > 0 && visible.every((id) => current.includes(id)); return allVisibleSelected ? current.filter((id) => !visibleSet.has(id)) : [...new Set([...current, ...visible])]; }); }
  async function moveQuestion() { if (!editingId) return; setSaving(true); try { await post({ action: "mover_questao", law_slug: law.slug, id: editingId, structure_id: moveDestination }); setForm((value) => ({ ...value, structure_id: moveDestination })); setOriginal((value) => value ? { ...value, structure_id: moveDestination } : value); setMoveOpen(false); setMessage("Questão movida dentro da mesma lei."); setRefresh((value) => value + 1); } catch (caught) { setEditorError(caught instanceof Error ? caught.message : "Não foi possível mover a questão."); } finally { setSaving(false); } }
  async function toggleStructureReview(structure: AdminQuestionStructureNode | null) { const reviewed = structure ? !reviewedStructures.has(structure.id) : !lawReviewed; const previous = new Set(reviewedStructures); const previousLawReviewed = lawReviewed; if (structure) setReviewedStructures((current) => { const next = new Set(current); if (reviewed) next.add(structure.id); else next.delete(structure.id); return next; }); else setLawReviewed(reviewed); setReviewSaving(structure?.id ?? "law"); setError(""); try { await post({ action: "marcar_revisao_estrutura", law_slug: law.slug, structure_id: structure?.id ?? null, reviewed }); } catch (caught) { setReviewedStructures(previous); setLawReviewed(previousLawReviewed); setError(caught instanceof Error ? caught.message : "Não foi possível salvar a marcação de conferência."); } finally { setReviewSaving(null); } }

  return <section className="grid gap-5">
    <header className="law-center-page-heading"><div><p className="law-center-kicker">Questões</p><h2>{law.titulo}</h2><p>{questionView === "ativas" ? `${total} questão(ões) no resultado atual · pesquisa e manutenção preservando UUIDs.` : "Identifique dispositivos sem questão, por trecho ou pela lei inteira."}</p></div><div className="law-center-quick-actions"><Link className="admin-button secondary" href={`/admin/leis/${encodeURIComponent(law.slug)}`}>← Central da Lei</Link>{questionView === "ativas" ? <><button type="button" className="admin-button secondary" disabled={Boolean(nodes.length && !structureId)} title={nodes.length ? structureId ? "Conferir todas as questões deste bloco" : "Selecione um bloco estrutural primeiro" : "Conferir todas as questões desta lei"} onClick={() => { setConferenceList(null); setConferenceOpen(true); }}>Modo conferência</button><button type="button" className="admin-button secondary" onClick={() => setConferenceListsOpen(true)}>Listas personalizadas</button><button type="button" className="admin-button secondary" onClick={() => { setBulkEditMode("edit"); setBulkEditField("total_artigos"); setBulkEditValue(null); setBulkEditScope(selectedQuestionIds.length ? "selected" : "results"); setBulkEditPreview(null); setBulkReplacePreview(null); setBulkEditCompletion(null); setBulkEditOpen(true); }}>Editar em lote{selectedQuestionIds.length ? ` (${selectedQuestionIds.length})` : ""}</button><button type="button" className="admin-button secondary" onClick={() => { setBulkEditMode("replace"); setBulkEditField("assunto"); setBulkEditScope(selectedQuestionIds.length ? "selected" : "results"); setBulkReplaceFind(""); setBulkReplaceValue(""); setBulkEditPreview(null); setBulkReplacePreview(null); setBulkEditCompletion(null); setBulkEditOpen(true); }}>Substituir texto{selectedQuestionIds.length ? ` (${selectedQuestionIds.length})` : ""}</button><button type="button" className="admin-button secondary" onClick={() => { setBulkEditMode("move"); setBulkEditField("structure_id"); setBulkEditValue(null); setBulkEditScope(selectedQuestionIds.length ? "selected" : "results"); setBulkEditPreview(null); setBulkReplacePreview(null); setBulkEditCompletion(null); setBulkEditOpen(true); }}>Mover em lote{selectedQuestionIds.length ? ` (${selectedQuestionIds.length})` : ""}</button><button type="button" className="admin-button danger" onClick={() => { setBulkOpen(true); setBulkSummary(null); setBulkConfirmation(""); }}>Excluir questões</button><button type="button" className="admin-button primary" onClick={() => newQuestion()}>Nova questão</button></> : null}</div></header>
    <nav className="flex border-b border-slate-200" role="tablist" aria-label="Visão de questões"><button type="button" role="tab" aria-selected={questionView === "ativas"} className={`px-4 py-3 text-sm font-black ${questionView === "ativas" ? "border-b-2 border-blue-600 text-blue-700" : "text-slate-600 hover:text-slate-900"}`} onClick={() => setQuestionView("ativas")}>Questões ativas</button><Link role="tab" aria-selected={questionView === "conflitos"} className={`px-4 py-3 text-sm font-black ${questionView === "conflitos" ? "border-b-2 border-blue-600 text-blue-700" : "text-slate-600 hover:text-slate-900"}`} href={`/admin/leis/${encodeURIComponent(law.slug)}/questoes?visao=conflitos`}>Conflitos de questões</Link><button type="button" role="tab" aria-selected={questionView === "sombra"} className={`px-4 py-3 text-sm font-black ${questionView === "sombra" ? "border-b-2 border-blue-600 text-blue-700" : "text-slate-600 hover:text-slate-900"}`} onClick={() => setQuestionView("sombra")}>Questões Sombra</button></nav>
    {questionView === "ativas" ? <article className="commercial-card grid gap-5 p-5"><header className="flex flex-wrap items-start justify-between gap-3"><div><p className="law-center-kicker">Localizar questões</p><h3 className="mt-1 text-lg font-black text-slate-950">Pesquisar nesta lei</h3><p className="mt-1 text-sm text-slate-600">Busque pelo conteúdo ou refine o resultado pelos filtros abaixo.</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-800">Filtros rápidos</span></header><label className="grid gap-2"><span className="text-sm font-black text-slate-800">Busca livre</span><input autoFocus className="min-h-12 w-full rounded-xl border border-slate-300 bg-slate-50 px-4 text-base shadow-inner transition placeholder:text-slate-400 focus:border-blue-500 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-100" type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Enunciado, artigo, assunto, ordem, estrutura, justificativa ou UUID" /></label><div className="grid gap-3 border-t border-slate-200 pt-4 sm:grid-cols-3"><label className="grid gap-2 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-bold text-slate-700"><span>Artigo</span><input className="min-h-10 rounded-lg border border-slate-300 bg-white px-3 font-normal text-slate-900" value={article} onChange={(event) => { setArticle(event.target.value); setPage(1); }} placeholder="Ex.: Art. 12" /></label><label className="grid gap-2 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-bold text-slate-700"><span>Gabarito</span><select className="min-h-10 rounded-lg border border-slate-300 bg-white px-3 font-normal text-slate-900" value={filter} onChange={(event) => { setFilter(event.target.value as AdminQuestionSearchFilter); setPage(1); }}>{answers.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label className="grid gap-2 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-bold text-slate-700"><span>Ordenar por</span><select className="min-h-10 rounded-lg border border-slate-300 bg-white px-3 font-normal text-slate-900" value={sort} onChange={(event) => { setSort(event.target.value as AdminQuestionSearchSort); setPage(1); }}>{sortOptions.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label></div></article> : null}
    {questionView === "ativas" ? <QuestionUuidPatchPreview key={law.slug} lawSlug={law.slug} /> : null}
    {questionView === "sombra" ? <div className="grid min-w-0 gap-4 lg:grid-cols-[minmax(260px,340px)_minmax(0,1fr)]"><aside className="grid content-start gap-3"><article className="commercial-card"><div className="flex items-center justify-between gap-2"><h3 className="font-black">Estrutura da lei</h3>{structureId ? <button type="button" className="admin-link-button" onClick={() => setStructureId(null)}>Limpar</button> : null}</div><StructureFilter nodes={nodes} counts={structureCounts} selected={structureId} onSelect={(id) => { setStructureId(id); setPage(1); }} reviewed={reviewedStructures} lawReviewed={lawReviewed} reviewSaving={reviewSaving} onToggleReview={(node) => void toggleStructureReview(node)} /></article><details><summary className="admin-button secondary cursor-pointer">Gerenciar estruturas</summary><div className="mt-3"><LawStructureAdmin lawSlug={law.slug} nodes={nodes} onReload={reloadStructure} onSelectNode={(node) => { setStructureId(node.id); setPage(1); }} selectNodeLabel="Filtrar Questões Sombra" /></div></details></aside><LawQuestionShadows key={shadowVersion} lawSlug={law.slug} structurePath={selectedStructurePath} onCreate={newShadowQuestion} /></div> : null}
    {questionView === "conflitos" && conflicts ? <ArticleSourceConflicts data={conflicts} filters={conflictFilters} baseHref={`/admin/leis/${encodeURIComponent(law.slug)}/questoes`} baseQuery={{ visao: "conflitos" }} /> : null}
    {message ? <p className="admin-alert success" role="status">{message}</p> : null}{error ? <p className="admin-alert error" role="alert">{error}</p> : null}
    {questionView === "ativas" ? <><div className="grid min-w-0 gap-4 lg:grid-cols-[minmax(260px,340px)_minmax(0,1fr)]"><aside className="grid content-start gap-3"><article className="commercial-card"><div className="flex items-center justify-between gap-2"><h3 className="font-black">Estrutura da lei</h3>{structureId ? <button type="button" className="admin-link-button" onClick={() => setStructureId(null)}>Limpar</button> : null}</div><StructureFilter nodes={nodes} counts={structureCounts} selected={structureId} onSelect={(id) => { setStructureId(id); setPage(1); }} reviewed={reviewedStructures} lawReviewed={lawReviewed} reviewSaving={reviewSaving} onToggleReview={(node) => void toggleStructureReview(node)} /></article><details><summary className="admin-button secondary cursor-pointer">Gerenciar estruturas</summary><div className="mt-3"><LawStructureAdmin lawSlug={law.slug} nodes={nodes} onReload={reloadStructure} onSelectNode={(node) => { setStructureId(node.id); setPage(1); }} selectNodeLabel="Filtrar questões" /></div></details></aside>
      <section className="grid min-w-0 content-start gap-3" aria-live="polite" aria-busy={loading}><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-black">Questões encontradas</h3><p className="mt-1 text-sm text-slate-600">{structureId ? `Estrutura: ${structurePath(structureId)}` : "Toda a lei"} · {total} questão(ões) · Abrangência: {resultRange.first_order ? `#${resultRange.first_order} — #${resultRange.last_order}` : "sem questões"}</p></div><div className="flex flex-wrap items-center justify-end gap-2"><span className="text-sm text-slate-600">{selectedQuestionIds.length ? `${selectedQuestionIds.length} selecionada(s)` : null}</span><button type="button" className="admin-button secondary" disabled={loading || !results.length} onClick={toggleAllVisibleQuestions}>{results.length > 0 && results.every((question) => selectedQuestionIds.includes(question.id)) ? "Desmarcar todas desta página" : "Selecionar todas desta página"}</button></div></div>{loading ? <p className="commercial-card commercial-loading">Pesquisando…</p> : results.map((question) => <div key={question.id} className="relative"><label className="absolute right-3 top-3 z-10 flex items-center gap-2 rounded bg-white/90 px-2 py-1 text-xs font-bold text-slate-700 shadow-sm"><input type="checkbox" checked={selectedQuestionIds.includes(question.id)} onChange={() => toggleQuestion(question.id)} />Selecionar</label><button type="button" onClick={() => void editQuestion(question.id)} className="commercial-card grid w-full gap-2 pr-28 text-left transition hover:border-blue-300 hover:shadow-sm"><div className="flex flex-wrap items-center gap-2"><strong className="text-blue-800">#{question.ordem}</strong><span className={`rounded-full px-2 py-0.5 text-xs font-bold ${question.resposta === "Certo" ? "bg-emerald-100 text-emerald-800" : "bg-red-100 text-red-800"}`}>{question.resposta}</span>{question.artigo ? <span className="text-sm font-bold text-slate-700">{question.artigo}</span> : null}</div><p className="line-clamp-3 text-sm text-slate-800"><HighlightedText text={question.pergunta_trecho || "Questão sem trecho disponível"} query={debouncedQuery} /></p><div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">{question.assunto ? <span>Assunto: {question.assunto}</span> : null}<span>Estrutura: {structurePath(question.structure_id) || "Sem estrutura"}</span></div></button></div>)}{!loading && !results.length ? <article className="commercial-card law-center-empty"><h3>Nenhuma questão encontrada</h3><p>Ajuste a busca ou os filtros selecionados.</p><div className="flex flex-wrap gap-2"><button type="button" className="admin-button primary" onClick={() => newQuestion()}>Cadastrar questão</button><Link className="admin-button secondary" href={`/admin/leis/${encodeURIComponent(law.slug)}/anki`}>Abrir Anki</Link></div></article> : null}</section>
    </div>
    {pages > 1 ? <nav className="flex items-center justify-center gap-3" aria-label="Paginação das questões"><button type="button" className="admin-button secondary" disabled={loading || page <= 1} onClick={() => setPage((value) => Math.max(1, value - 1))}>Anterior</button><span className="text-sm">Página {page} de {pages}</span><button type="button" className="admin-button secondary" disabled={loading || page >= pages} onClick={() => setPage((value) => value + 1)}>Próxima</button></nav> : null}</> : null}
    {editorOpen ? <div className="fixed inset-0 z-50 bg-slate-950/45" role="presentation"><div ref={titleRef} tabIndex={-1} className="absolute inset-0 overflow-y-auto bg-slate-50 p-3 outline-none xl:left-auto xl:w-[min(94vw,1120px)] xl:p-5" role="dialog" aria-modal="true" aria-labelledby="admin-question-editor-title"><div className="mb-3 flex justify-end"><button type="button" className="admin-button secondary" disabled={saving} onClick={() => returnHref ? window.location.assign(returnHref) : setEditorOpen(false)}>Fechar</button></div><AdminQuestionEditor lawName={law.titulo} nodes={nodes} value={form} original={original} editing={Boolean(editingId)} saving={saving} error={editorError} onChange={setForm} onSubmit={(event) => void save(event)} onCancel={() => returnHref ? window.location.assign(returnHref) : setEditorOpen(false)} onPrevious={previousId ? () => navigateToQuestion(previousId) : undefined} onNext={nextId ? () => navigateToQuestion(nextId) : undefined} onDuplicate={duplicateQuestion} onMove={() => { setMoveDestination(form.structure_id); setMoveOpen(true); }} onDelete={() => void askDeleteQuestion()} showPreview /></div></div> : null}
    {deletionSummary ? <DeletionConfirmation summary={deletionSummary} confirmation={deleteConfirmation} saving={saving} targetLabel="questão" onConfirmation={setDeleteConfirmation} onCancel={() => setDeletionSummary(null)} onConfirm={() => void deleteQuestion()} /> : null}
    {bulkOpen ? <BulkDeletionDialog scope={bulkScope} selectedStructure={structureId !== null} summary={bulkSummary} confirmation={bulkConfirmation} saving={saving} onScope={setBulkScope} onConfirmText={setBulkConfirmation} onPreview={() => void askBulkDelete()} onCancel={() => { setBulkOpen(false); setBulkSummary(null); }} onDelete={() => void deleteBulkQuestions()} /> : null}
    {bulkEditOpen ? <BulkQuestionEditDialog mode={bulkEditMode} scope={bulkEditScope} field={bulkEditField} value={bulkEditValue} find={bulkReplaceFind} replace={bulkReplaceValue} nodes={nodes} structurePath={structurePath} selectedCount={selectedQuestionIds.length} preview={bulkEditMode === "replace" ? bulkReplacePreview : bulkEditPreview} completion={bulkEditCompletion} saving={saving} onScope={(scope) => { setBulkEditScope(scope); setBulkEditPreview(null); setBulkReplacePreview(null); }} onField={(field) => { setBulkEditField(field); setBulkEditValue(field === "resposta" ? "Certo" : field === "total_artigos" ? null : ""); setBulkEditPreview(null); setBulkReplacePreview(null); }} onValue={(value) => { setBulkEditValue(value); setBulkEditPreview(null); }} onFind={(value) => { setBulkReplaceFind(value); setBulkReplacePreview(null); }} onReplace={(value) => { setBulkReplaceValue(value); setBulkReplacePreview(null); }} onPreview={() => void (bulkEditMode === "replace" ? previewBulkTextReplacement() : previewBulkEdit())} onCancel={() => { setBulkEditOpen(false); setBulkEditPreview(null); setBulkReplacePreview(null); setBulkEditCompletion(null); }} onApply={() => void (bulkEditMode === "replace" ? applyBulkTextReplacement() : applyBulkEdit())} /> : null}
    {moveOpen ? <div className="admin-modal-backdrop" role="presentation"><section className="admin-modal" role="dialog" aria-modal="true" aria-labelledby="move-question-title"><h2 id="move-question-title">Mover para outra estrutura</h2><label>Destino<select value={moveDestination ?? ""} onChange={(event) => setMoveDestination(event.target.value ? Number(event.target.value) : null)}><option value="">Sem estrutura</option>{nodes.map((node) => <option key={node.id} value={node.id}>{structurePath(node.id)}</option>)}</select></label><div className="admin-modal-actions"><button className="admin-button secondary" type="button" onClick={() => setMoveOpen(false)}>Cancelar</button><button className="admin-button primary" type="button" disabled={saving} onClick={() => void moveQuestion()}>Mover</button></div></section></div> : null}
    {conferenceListsOpen ? <AdminQuestionConferenceLists law={law} onClose={() => setConferenceListsOpen(false)} onOpen={(list) => { setConferenceListsOpen(false); setConferenceList(list); setConferenceOpen(true); }} /> : null}
    {conferenceOpen && (conferenceList || structureId || !nodes.length) ? <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/45 p-2 sm:p-4"><main className="mx-auto min-h-[calc(100vh-1rem)] w-full max-w-[90rem] sm:min-h-[calc(100vh-2rem)]"><AdminQuestionConference law={law} nodes={nodes} structureId={conferenceList ? null : structureId} structureName={conferenceList?.nome ?? (structureId ? structurePath(structureId) : "Lei completa")} customList={conferenceList ?? undefined} onClose={() => { setConferenceOpen(false); setConferenceList(null); }} onChanged={() => setRefresh((value) => value + 1)} /></main></div> : null}
  </section>;
}

function StructureFilter({ nodes, counts, selected, onSelect, reviewed, lawReviewed, reviewSaving, onToggleReview, parentId = null, depth = 0 }: { nodes: AdminQuestionStructureNode[]; counts: Record<number, number>; selected: number | null; onSelect: (id: number) => void; reviewed: Set<number>; lawReviewed: boolean; reviewSaving: number | "law" | null; onToggleReview: (node: AdminQuestionStructureNode | null) => void; parentId?: number | null; depth?: number }) { const children = nodes.filter((node) => node.parent_id === parentId).sort((a, b) => a.ordem - b.ordem || a.nome.localeCompare(b.nome, "pt-BR")); if (!children.length && depth === 0) return <div className="mt-3 flex items-center justify-between gap-2 rounded-lg bg-slate-50 px-2 py-1.5"><span className="text-sm font-bold text-slate-700">Lei completa</span><button type="button" className={`shrink-0 rounded px-1.5 py-1 text-xs ${lawReviewed ? "font-black text-green-700" : "text-slate-400 hover:text-slate-700"}`} aria-pressed={lawReviewed} aria-label={lawReviewed ? "Desmarcar lei completa como conferida" : "Marcar lei completa como conferida"} title={lawReviewed ? "Desmarcar como conferido" : "Marcar como conferido"} disabled={reviewSaving === "law"} onClick={(event) => { event.stopPropagation(); onToggleReview(null); }}>{lawReviewed ? "✓ Conferido" : "Marcar como conferido"}</button></div>; return <ul className={depth ? "mt-1" : "mt-3"}>{children.map((node) => <li key={node.id}><div className="flex items-center gap-1" style={{ paddingLeft: depth * 14 }}><button type="button" aria-pressed={selected === node.id} className={`min-w-0 flex-1 rounded-lg px-2 py-1.5 text-left text-sm ${selected === node.id ? "bg-blue-100 font-black text-blue-800" : "hover:bg-slate-100"}`} onClick={() => onSelect(node.id)}><span className="flex min-w-0 items-start justify-between gap-2"><span className="min-w-0">{node.nome}</span><span className="shrink-0 text-xs font-bold text-slate-500" aria-label={`${counts[node.id] ?? 0} questões neste deck e subdecks`}>{counts[node.id] ?? 0}</span></span></button><button type="button" className={`shrink-0 rounded px-1.5 py-1 text-xs ${reviewed.has(node.id) ? "font-black text-green-700" : "text-slate-400 hover:text-slate-700"}`} aria-pressed={reviewed.has(node.id)} aria-label={reviewed.has(node.id) ? `Desmarcar ${node.nome} como conferido` : `Marcar ${node.nome} como conferido`} title={reviewed.has(node.id) ? "Desmarcar como conferido" : "Marcar como conferido"} disabled={reviewSaving === node.id} onClick={(event) => { event.stopPropagation(); onToggleReview(node); }}>{reviewed.has(node.id) ? "✓ Conferido" : "Marcar como conferido"}</button></div><StructureFilter nodes={nodes} counts={counts} selected={selected} onSelect={onSelect} reviewed={reviewed} lawReviewed={lawReviewed} reviewSaving={reviewSaving} onToggleReview={onToggleReview} parentId={node.id} depth={depth + 1} /></li>)}</ul>; }

function DeletionConfirmation({ summary, confirmation, saving, targetLabel, onConfirmation, onCancel, onConfirm }: { summary: DeletionSummary; confirmation: string; saving: boolean; targetLabel: string; onConfirmation: (value: string) => void; onCancel: () => void; onConfirm: () => void }) {
  return <div className="admin-modal-backdrop" role="presentation"><section className="admin-modal" role="dialog" aria-modal="true" aria-labelledby="delete-question-title"><h2 id="delete-question-title">Excluir {targetLabel} definitivamente?</h2><p>Serão removidas {summary.questions_count} questão(ões), {summary.campaigns_count} campanha(s), {summary.answers_count} resposta(s) e {summary.progresses_count} progresso(s) ativo(s).</p>{summary.campaigns.length ? <div><h3 className="font-bold">Campanhas afetadas e titulares</h3><ul>{summary.campaigns.map((campaign) => <li key={campaign.id}>{campaign.nome || "Aluno sem nome"} · {campaign.email || campaign.aluno_id}{campaign.is_requesting_admin ? " · conta administrativa" : " · outro aluno"}</li>)}</ul></div> : <p>Nenhuma campanha será removida.</p>}<p className="admin-alert error">A exclusão é definitiva e não possui lixeira ou restauração.</p>{summary.requires_confirmation ? <p className="admin-alert">Há campanhas de outros alunos entre os impactos.</p> : null}<div className="admin-modal-actions"><button className="admin-button secondary" type="button" disabled={saving} onClick={onCancel}>Cancelar</button><button className="admin-button danger" type="button" disabled={saving || (summary.requires_confirmation && confirmation !== "EXCLUIR")} onClick={onConfirm}>{saving ? "Excluindo…" : `Excluir ${targetLabel} e campanhas afetadas`}</button></div></section></div>;
}

function BulkDeletionDialog({ scope, selectedStructure, summary, confirmation, saving, onScope, onConfirmText, onPreview, onCancel, onDelete }: { scope: BulkScope; selectedStructure: boolean; summary: DeletionSummary | null; confirmation: string; saving: boolean; onScope: (scope: BulkScope) => void; onConfirmText: (value: string) => void; onPreview: () => void; onCancel: () => void; onDelete: () => void }) {
  return <div className="admin-modal-backdrop" role="presentation"><section className="admin-modal" role="dialog" aria-modal="true" aria-labelledby="bulk-delete-questions-title"><h2 id="bulk-delete-questions-title">Excluir questões definitivamente</h2><p>As estruturas serão preservadas. A prévia calcula campanhas inteiras, respostas e progressos que precisam ser removidos.</p><label>Escopo<select value={scope} disabled={saving || Boolean(summary)} onChange={(event) => onScope(event.target.value as BulkScope)}><option value="structure" disabled={!selectedStructure}>Da estrutura selecionada e descendentes{selectedStructure ? "" : " (selecione uma estrutura antes)"}</option><option value="results">Do resultado atual dos filtros</option><option value="all">Todas as questões desta lei</option></select></label>{!summary ? <div className="admin-modal-actions"><button type="button" className="admin-button secondary" disabled={saving} onClick={onCancel}>Cancelar</button><button type="button" className="admin-button danger" disabled={saving || (scope === "structure" && !selectedStructure)} onClick={onPreview}>{saving ? "Calculando…" : "Ver prévia"}</button></div> : <><p>Serão removidas <strong>{summary.questions_count} questão(ões)</strong>, <strong>{summary.campaigns_count} campanha(s)</strong>, {summary.answers_count} resposta(s) e {summary.progresses_count} progresso(s). Nenhuma estrutura será excluída.</p>{summary.campaigns.length ? <details open><summary>Campanhas e titulares afetados</summary><ul>{summary.campaigns.map((campaign) => <li key={campaign.id}>{campaign.nome || "Aluno sem nome"} · {campaign.email || campaign.aluno_id}{campaign.is_requesting_admin ? " · conta administrativa" : " · outro aluno"}</li>)}</ul></details> : <p>Nenhuma campanha será removida.</p>}<p className="admin-alert error">A exclusão em massa é definitiva e será executada em uma única transação.</p><div className="admin-modal-actions"><button type="button" className="admin-button secondary" disabled={saving} onClick={onCancel}>Cancelar</button><button type="button" className="admin-button danger" disabled={saving || confirmation !== "EXCLUIR"} onClick={onDelete}>{saving ? "Excluindo…" : "Excluir questões e campanhas afetadas"}</button></div></>}</section></div>;
}

function structureDestinationOrder(nodes: AdminQuestionStructureNode[]) {
  const visit = (parentId: number | null): AdminQuestionStructureNode[] => nodes.filter((node) => node.parent_id === parentId).sort(compareQuestionStructureNames).flatMap((node) => [node, ...visit(node.id)]);
  return visit(null);
}

function BulkQuestionEditDialog({ mode, scope, field, value, find, replace, nodes, structurePath, selectedCount, preview, completion, saving, onScope, onField, onValue, onFind, onReplace, onPreview, onCancel, onApply }: { mode: "edit" | "move" | "replace"; scope: BulkQuestionEditScope; field: QuestionEditableField; value: unknown; find: string; replace: string; nodes: AdminQuestionStructureNode[]; structurePath: (id: number | null) => string; selectedCount: number; preview: BulkEditPreview | BulkTextReplacementPreview | null; completion: string | null; saving: boolean; onScope: (scope: BulkQuestionEditScope) => void; onField: (field: QuestionEditableField) => void; onValue: (value: unknown) => void; onFind: (value: string) => void; onReplace: (value: string) => void; onPreview: () => void; onCancel: () => void; onApply: () => void }) {
  const movingStructure = mode === "move";
  const replacingText = mode === "replace";
  const replacementPreview = preview && "find" in preview ? preview : null;
  const nullable = !movingStructure && !replacingText && !["pergunta", "resposta", "ordem"].includes(field);
  const hasDestination = typeof value === "number" && Number.isSafeInteger(value) && value > 0;
  const destinations = structureDestinationOrder(nodes);
  const selectedDestination = hasDestination ? structurePath(value) : "";
  const destinationLabel = (node: AdminQuestionStructureNode) => {
    let depth = 0;
    for (let parentId = node.parent_id; parentId !== null; parentId = nodes.find((candidate) => candidate.id === parentId)?.parent_id ?? null) depth += 1;
    return `${"— ".repeat(depth)}${node.nome}`;
  };
  const valueControl = field === "resposta" ? <select value={String(value ?? "Certo")} disabled={Boolean(preview) || saving} onChange={(event) => onValue(event.target.value)}>{QUESTION_ANSWERS.map((answer) => <option key={answer}>{answer}</option>)}</select>
    : movingStructure ? <><select value={value == null ? "" : String(value)} disabled={Boolean(preview) || saving} onChange={(event) => onValue(event.target.value ? Number(event.target.value) : null)}><option value="" disabled>Selecione o bloco de destino</option>{destinations.map((node) => <option key={node.id} value={node.id}>{destinationLabel(node)}</option>)}</select>{selectedDestination ? <p className="mt-2 break-words rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-normal text-slate-700"><span className="font-bold text-slate-900">Destino:</span> {selectedDestination}</p> : null}</>
    : field === "total_artigos" ? <input type="number" min="0" value={value == null ? "" : String(value)} disabled={Boolean(preview) || saving} onChange={(event) => onValue(event.target.value === "" ? null : Number(event.target.value))} />
    : field === "pergunta" || field === "justificativa" || field === "legislacao" ? <QuestionRichEditor label="Novo valor" required={field === "pergunta"} disabled={Boolean(preview) || saving} value={String(value ?? "")} onChange={onValue} />
    : <input value={String(value ?? "")} disabled={Boolean(preview) || saving} onChange={(event) => onValue(event.target.value)} />;
  if (completion) return <div className="admin-modal-backdrop" role="presentation"><section className="admin-modal max-w-xl" role="dialog" aria-modal="true" aria-labelledby="bulk-edit-complete-title"><p className="law-center-kicker">Manutenção em lote</p><h2 id="bulk-edit-complete-title" className="mt-1">Alteração concluída</h2><section className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 p-4" role="status"><p className="font-black text-emerald-900">Operação aplicada com sucesso.</p><p className="mt-2 text-sm text-emerald-900">{completion}</p></section><div className="admin-modal-actions mt-5"><button type="button" className="admin-button primary" onClick={onCancel}>Fechar</button></div></section></div>;
  return <div className="admin-modal-backdrop" role="presentation"><section className="admin-modal max-h-[calc(100dvh-2rem)] max-w-3xl overflow-y-auto" role="dialog" aria-modal="true" aria-labelledby="bulk-edit-questions-title">
    <header className="border-b border-slate-200 pb-4"><p className="law-center-kicker">Manutenção em lote</p><h2 id="bulk-edit-questions-title" className="mt-1">{movingStructure ? "Mover questões" : replacingText ? "Substituir texto" : "Editar questões"}</h2><p className="mt-2 text-sm text-slate-600">{movingStructure ? "Escolha o bloco de destino. UUIDs, campanhas e progresso são preservados." : replacingText ? "Localize todas as ocorrências idênticas no campo escolhido e substitua-as após conferir a prévia." : "Altere um único campo por operação. UUIDs, campanhas e progresso são preservados."}</p></header>
    <div className={`grid gap-4 py-5 ${movingStructure ? "" : "sm:grid-cols-2"}`}>
      <label className="grid gap-2 font-bold">Abrangência<select value={scope} disabled={Boolean(preview) || saving} onChange={(event) => onScope(event.target.value as BulkQuestionEditScope)}><option value="selected">Questões selecionadas{selectedCount ? ` (${selectedCount})` : ""}</option><option value="results">Resultado atual dos filtros</option><option value="all">Todas as questões desta lei</option></select></label>
      {!movingStructure ? <label className="grid gap-2 font-bold">Campo<select value={field} disabled={Boolean(preview) || saving} onChange={(event) => onField(event.target.value as QuestionEditableField)}>{Object.entries(QUESTION_BULK_FIELD_LABELS).filter(([key]) => replacingText ? QUESTION_TEXT_REPLACE_FIELDS.includes(key as QuestionTextReplaceField) : key !== "structure_id").map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label> : null}
    </div>
    <section className="rounded-xl border border-slate-200 bg-slate-50 p-4">{replacingText ? <div className="grid gap-4 sm:grid-cols-2"><label className="grid gap-2 font-bold">Texto a localizar<input value={find} disabled={Boolean(preview) || saving} onChange={(event) => onFind(event.target.value)} /></label><label className="grid gap-2 font-bold">Substituir por<input value={replace} disabled={Boolean(preview) || saving} onChange={(event) => onReplace(event.target.value)} /></label><p className="sm:col-span-2 text-sm text-slate-600">A busca é literal, diferencia maiúsculas de minúsculas e só troca ocorrências completas. Deixe “Substituir por” vazio para remover o texto encontrado.</p></div> : <><label className="grid gap-2 font-bold">{movingStructure ? "Destino estrutural" : "Novo valor"}{valueControl}</label>{movingStructure ? <p className="mt-2 text-sm text-slate-600">As questões manterão o conteúdo e passarão a pertencer ao bloco selecionado.</p> : nullable ? <p className="mt-2 text-sm text-slate-600">Deixe vazio para limpar este campo.</p> : <p className="mt-2 text-sm text-slate-600">Este campo é obrigatório e não pode ficar vazio.</p>}</>}</section>
    {!preview ? <div className="admin-modal-actions mt-5 border-t border-slate-200 pt-4"><button type="button" className="admin-button secondary" disabled={saving} onClick={onCancel}>Cancelar</button><button type="button" className="admin-button primary" disabled={saving || (scope === "selected" && !selectedCount) || (movingStructure && !hasDestination) || (replacingText && !find.trim())} onClick={onPreview}>{saving ? "Calculando…" : movingStructure ? "Ver prévia da movimentação" : replacingText ? "Ver prévia da substituição" : "Ver prévia"}</button></div> : <><section className="mt-5 rounded-xl border border-blue-200 bg-blue-50 p-4"><h3 className="font-black">Prévia da {movingStructure ? "movimentação" : replacingText ? "substituição" : "alteração"}</h3><p className="mt-1 text-sm">Lei atual · {scope === "selected" ? "questões selecionadas" : scope === "results" ? "resultado atual dos filtros" : "todas as questões da lei"} · <strong>{QUESTION_BULK_FIELD_LABELS[field]}</strong>{replacementPreview ? <> · <strong>{questionFieldDisplayValue(replacementPreview.find)}</strong> → <strong>{questionFieldDisplayValue(replacementPreview.replace)}</strong></> : <> → <strong>{questionFieldDisplayValue((preview as BulkEditPreview).value)}</strong></>}</p><p className="mt-2 text-sm"><strong>{preview.changed_count}</strong> questão(ões) serão alteradas; {preview.unchanged_count} já possuem esse valor.</p>{preview.sample.length ? <details open className="mt-3"><summary className="cursor-pointer font-bold">Exemplos de alteração</summary><ul className="mt-2 list-disc pl-5 text-sm">{preview.sample.map((item) => <li key={item.id}><code>{item.id.slice(0, 8)}</code>: {questionFieldDisplayValue(item.before)} → {questionFieldDisplayValue(item.after)}</li>)}</ul></details> : null}</section><p className="mt-4 text-sm text-slate-600">A confirmação verifica novamente os valores anteriores. Se outra edição ocorrer, será exigida uma nova prévia.</p><div className="admin-modal-actions mt-5 border-t border-slate-200 pt-4"><button type="button" className="admin-button secondary" disabled={saving} onClick={onCancel}>Cancelar</button><button type="button" className="admin-button primary" disabled={saving || !preview.changed_count} onClick={onApply}>{saving ? "Aplicando…" : movingStructure ? `Confirmar movimentação de ${preview.changed_count} questão(ões)` : replacingText ? `Confirmar substituição em ${preview.changed_count} questão(ões)` : `Confirmar edição de ${preview.changed_count} questão(ões)`}</button></div></>}
  </section></div>;
}
